import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import styled from 'styled-components';

const EmployeePage = () => {
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver"); // Default role
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [employees, setEmployees] = useState([]);
  const [filteredEmployees, setFilteredEmployees] = useState([]);

  // Function to add employee
  const addEmployee = async () => {
    try {
      const response = await axios.post("http://localhost:5001/api/addEmployee", {
        registration_number: registrationNumber,
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
      });
      console.log("Employee added:", response.data);
    } catch (error) {
      console.error("Error adding employee:", error);
    }
  };

  // Function to fetch employees by registration number and role
  const fetchEmployeesByRole = async (role) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employeesByRole/${registrationNumber}/${role}`
      );
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  // Render employee list based on role
  const handleRoleChange = (e) => {
    setEmployeeRole(e.target.value);
    fetchEmployeesByRole(e.target.value); // Fetch employees of selected role
  };

  return (
    <Container>
      <Header>
        <LorryTitle>{registrationNumber}</LorryTitle>
      </Header>

      <Form onSubmit={handleFormSubmit}>
        <FormTitle>Add New Employee</FormTitle>
        <Input
          type="text"
          name="name"
          placeholder="Name"
          value={employeeForm.name}
          onChange={handleFormChange}
        />
        <Input
          type="text"
          name="phone"
          placeholder="Phone Number"
          value={employeeForm.phone}
          onChange={handleFormChange}
        />
        <Select name="role" value={employeeForm.role} onChange={handleFormChange}>
          <option value="">Select Role</option>
          <option value="drivers">Driver</option>
          <option value="drillers">Driller</option>
          <option value="managers">Lorry Manager</option>
          <option value="workers">Worker</option>
        </Select>
        <Input
          type="number"
          name="salary"
          placeholder="Fixed Salary"
          value={employeeForm.salary}
          onChange={handleFormChange}
        />
        <Button type="submit">Add Employee</Button>
      </Form>

      <EmployeeRoles>
        {['drivers', 'drillers', 'managers', 'workers'].map((role) => (
          <RoleSection key={role}>
            <RoleTitle onClick={() => handleRoleClick(role)}>{role.charAt(0).toUpperCase() + role.slice(1)}</RoleTitle>
            <EmployeeList>
              {employees[role].map((employee) => (
                <EmployeeItem key={employee.phone} onClick={() => handleEmployeeClick(employee)}>
                  {employee.name} ({employee.phone})
                </EmployeeItem>
              ))}
            </EmployeeList>
          </RoleSection>
        ))}
      </EmployeeRoles>

      {selectedEmployee && (
        <EmployeeDetailsCard>
          <CardTitle>{selectedEmployee.name}</CardTitle>
          <CardDetails>
            <DetailRow>
              <DetailLabel>Name</DetailLabel>
              <DetailValue>{selectedEmployee.name}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Phone</DetailLabel>
              <DetailValue>{selectedEmployee.phone}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Fixed Salary</DetailLabel>
              <DetailValue>{selectedEmployee.fixed_salary}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Expenses</DetailLabel>
              <DetailValue>{selectedEmployee.expenses || 'N/A'}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Earned Money</DetailLabel>
              <DetailValue>{selectedEmployee.earned_money || 'N/A'}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Remaining Amount</DetailLabel>
              <DetailValue>{selectedEmployee.remaining_amount || 'N/A'}</DetailValue>
            </DetailRow>
            <DetailRow>
              <DetailLabel>Days Worked</DetailLabel>
              <DetailValue>{selectedEmployee.days_worked || 'N/A'}</DetailValue>
            </DetailRow>
          </CardDetails>
        </EmployeeDetailsCard>
      )}
    </Container>
  );
};

// Styled Components

const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Form = styled.form`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const FormTitle = styled.h2`
  font-size: 1.5rem;
  margin-bottom: 10px;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Button = styled.button`
  width: 100%;
  padding: 12px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s ease;

  &:hover {
    background-color: #45a049;
  }
`;

const EmployeeRoles = styled.div`
  display: flex;
  flex-wrap: wrap;
  margin-top: 20px;
`;

const RoleSection = styled.div`
  width: 48%;
  margin: 10px 1%;
  background-color: #ffffff;
  padding: 15px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const RoleTitle = styled.h3`
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 10px;
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  cursor: pointer;
  padding: 5px;
  border-bottom: 1px solid #ccc;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const EmployeeDetailsCard = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 30px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const CardTitle = styled.h2`
  font-size: 1.5rem;
  margin-bottom: 15px;
`;

const CardDetails = styled.div`
  font-size: 1rem;
`;

const DetailRow = styled.div`
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
`;

const DetailLabel = styled.div`
  font-weight: bold;
  color: #333;
`;

const DetailValue = styled.div`
  color: #555;
`;

export default EmployeePage;
